import type { SubagentRunInfo } from '../src/index.ts'

const roots: string[] = []
afterEach(() => {
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 })
})

const testSignal = new AbortController().signal

/** Compose the continuable stack with a scripted provider; persistence is optional. */
async function setup(script: ConstructorParameters<typeof MockAdapter>[0], options: { persistence: boolean }) {
  const ctx = new Context()
  await mountAgentLoopTestDependencies(ctx)
  let disposePersistence: (() => Promise<void>) | undefined
  if (options.persistence) {
    const root = mkdtempSync(join(tmpdir(), 'dsh-subagent-persistence-unavailable-'))
    roots.push(root)
    const fiber = await ctx.plugin(JsonlSessionPersistence, { root })
    disposePersistence = () => fiber.dispose()
  }
  await ctx.plugin(AgentLoop, { agents: [] })
  await ctx.plugin(SubagentRuntime)
  await ctx.plugin(SubagentSpawn, { providerName: 'spawn' })
  const adapter = new MockAdapter(script)
  ctx.llm.registerAdapter(['mock'], adapter)
  const parent = ctx.agentLoop.create(SessionId('parent'), { provider: 'mock', model: 'mock' })
  // Every child settlement wakes its parent; keep the parent off the scripted model.
  ctx.on('agent/pre-step', async ({ agent }, next) => {
    if (agent !== parent) return next()
    return { kind: 'reject' as const }
  })
  const starts: SubagentRunInfo[] = []
  ctx.on('subagent/start', info => void starts.push(info))
  return { ctx, parent, adapter, starts, disposePersistence }
}

function startSpec(parent: Agent) {
  return {
    provider: 'spawn',
    label: 'child task',
    request: { prompt: [{ type: 'text' as const, text: 'child task' }], parent },
    signal: testSignal,
  }
}

function sessionIds(ctx: Context): string[] {
  return ctx.sessions.list().map(session => session.id).sort()
}

/** Assert the rejection is the persistence refusal that names the backend to load. */
async function expectPersistenceRefusal(operation: Promise<unknown>): Promise<void> {
  const error = await operation.then(() => undefined, (rejection: unknown) => rejection)
  expect(error).toBeInstanceOf(SubagentError)
  expect((error as SubagentError).code).toBe('PERSISTENCE_UNAVAILABLE')
  expect((error as SubagentError).message).toContain('dsh-session-persistence')
}

describe('continuable subagents without a session-persistence backend', () => {
  it('startContinuable rejects with PERSISTENCE_UNAVAILABLE before creating a child or emitting subagent/start', async () => {
    const { ctx, parent, adapter, starts } = await setup([textResponse('unused')], { persistence: false })
    const before = sessionIds(ctx)

    await expectPersistenceRefusal(ctx.subagents.startContinuable(startSpec(parent)))

    expect(sessionIds(ctx)).toEqual(before)
    expect(ctx.agents.list().map(agent => agent.id)).toEqual([SessionId('parent')])
    expect(starts).toEqual([])
    expect(adapter.requests).toEqual([])
  })

  it('a cold follow-up rejects with PERSISTENCE_UNAVAILABLE once the backend is gone, creating no session and no subagent/start', async () => {
    const { ctx, parent, starts, disposePersistence } = await setup([textResponse('answer')], { persistence: true })
    const started = await ctx.subagents.startContinuable(startSpec(parent))
    await vi.waitFor(() => { expect(ctx.agents.get(started.childId)).toBeUndefined() }, { timeout: 5_000 })
    expect(starts).toHaveLength(1)
    await disposePersistence!()
    const before = sessionIds(ctx)

    await expectPersistenceRefusal(ctx.subagents.followup(
      parent,
      started.childId,
      [{ type: 'text', text: 'more work' }],
      { source: { kind: 'user' }, signal: testSignal },
    ))

    expect(sessionIds(ctx)).toEqual(before)
    expect(ctx.agents.get(started.childId)).toBeUndefined()
    expect(starts).toHaveLength(1)
  })
})
"}

